arguments.command:
mkdir -p /app/output && cat << 'EOF' > /tmp/poster.html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800;900&display=swap');

  :root {
    --bg-color: #050b14;
    --card-bg: #0b162c;
    --text-primary: #ffffff;
    --text-secondary: #8892b0;
    --accent-cyan: #00e5ff;
    --accent-blue: #0077ff;
    --accent-teal: #1de9b6;
  }

  body {
    margin: 0;
    padding: 0;
    width: 2376px;
    height: 3364px;
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    position: relative;
    overflow: hidden;
  }

  .bg-pattern {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: 
      radial-gradient(circle at 15% 50%, rgba(0, 229, 255, 0.04) 0%, transparent 50%),
      radial-gradient(circle at 85% 30%, rgba(0, 119, 255, 0.05) 0%, transparent 50%);
    z-index: 0;
    pointer-events: none;
  }

  .container {
    position: relative;
    z-index: 1;
    padding: 120px 140px;
    display: flex;
    flex-direction: column;
    height: 100%;
    box-sizing: border-box;
    gap: 70px;
  }

  header {
    border-bottom: 4px solid var(--accent-blue);
    padding-bottom: 40px;
  }

  h1 {
    font-size: 110px;
    font-weight: 900;
    margin: 0;
    line-height: 1.1;
    letter-spacing: -2px;
    background: linear-gradient(90deg, #fff, var(--accent-cyan));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .subtitle {
    font-size: 48px;
    font-weight: 300;
    color: var(--text-secondary);
    margin-top: 25px;
    max-width: 1900px;
    line-height: 1.4;
  }

  .hero-stat {
    text-align: center;
    padding: 90px 0;
    background: linear-gradient(180deg, rgba(11,22,44,0) 0%, rgba(0,119,255,0.15) 50%, rgba(11,22,44,0) 100%);
    border-radius: 40px;
    margin: 20px 0;
  }

  .hero-number {
    font-size: 300px;
    font-weight: 900;
    margin: 0;
    color: var(--accent-cyan);
    line-height: 1;
    text-shadow: 0 0 80px rgba(0, 229, 255, 0.4);
    letter-spacing: -5px;
  }

  .hero-label {
    font-size: 65px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 4px;
    margin-top: 30px;
    color: var(--text-primary);
  }

  .hero-sublabel {
    font-size: 45px;
    color: var(--accent-teal);
    margin-top: 20px;
    font-weight: 400;
  }

  .main-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 70px;
    flex-grow: 1;
  }

  .card {
    background-color: var(--card-bg);
    border-radius: 40px;
    padding: 70px;
    border: 1px solid rgba(0, 229, 255, 0.15);
    box-shadow: 0 20px 60px rgba(0,0,0,0.4);
    display: flex;
    flex-direction: column;
  }

  .card-title {
    font-size: 55px;
    font-weight: 800;
    margin-bottom: 50px;
    color: var(--accent-cyan);
    text-transform: uppercase;
    letter-spacing: 2px;
    display: flex;
    align-items: center;
    gap: 20px;
  }

  .card-title::before {
    content: '';
    display: inline-block;
    width: 14px;
    height: 55px;
    background-color: var(--accent-blue);
    border-radius: 7px;
  }

  /* Section 1 */
  .population-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    margin-bottom: 50px;
  }

  .pop-highlight {
    background: linear-gradient(135deg, rgba(0,119,255,0.2) 0%, rgba(0,229,255,0.05) 100%);
    border: 2px solid rgba(0, 229, 255, 0.4);
    border-radius: 25px;
    padding: 50px 40px;
    text-align: center;
  }

  .pop-highlight .country {
    font-size: 50px;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 2px;
  }

  .pop-highlight .value {
    font-size: 110px;
    font-weight: 900;
    color: var(--text-primary);
    margin: 20px 0;
    line-height: 1;
  }

  .pop-highlight .label {
    font-size: 34px;
    color: var(--accent-cyan);
    font-weight: 600;
  }

  .other-countries {
    font-size: 36px;
    line-height: 1.6;
    color: var(--text-secondary);
  }

  .other-countries span {
    color: var(--text-primary);
    font-weight: 600;
  }

  /* Section 2 */
  .chart-container {
    display: flex;
    flex-direction: column;
    gap: 28px;
    flex-grow: 1;
    justify-content: center;
  }

  .bar-row {
    display: flex;
    align-items: center;
    gap: 25px;
  }

  .bar-label {
    width: 200px;
    font-size: 36px;
    font-weight: 600;
    color: var(--text-secondary);
    text-align: right;
  }

  .bar-track {
    flex-grow: 1;
    height: 48px;
    background-color: rgba(255,255,255,0.05);
    border-radius: 24px;
    overflow: hidden;
    position: relative;
  }

  .bar-fill {
    height: 100%;
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 20px;
    font-size: 28px;
    font-weight: 800;
    color: #000;
  }

  .bar-fill.high { background: linear-gradient(90deg, var(--accent-blue), var(--accent-cyan)); }
  .bar-fill.med { background: linear-gradient(90deg, #0055aa, var(--accent-teal)); }
  .bar-fill.low { background: linear-gradient(90deg, #2a3b5c, #5b79a8); color: #fff; }

  /* Section 3 */
  .usage-stat {
    display: flex;
    align-items: center;
    gap: 50px;
    margin-bottom: 60px;
    background: rgba(0, 229, 255, 0.08);
    padding: 50px;
    border-radius: 25px;
    border: 1px solid rgba(0, 229, 255, 0.2);
  }

  .usage-stat-val {
    font-size: 130px;
    font-weight: 900;
    color: var(--accent-teal);
    line-height: 1;
  }

  .usage-stat-desc {
    font-size: 42px;
    font-weight: 400;
    line-height: 1.4;
    color: var(--text-primary);
  }

  .platforms {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  .platform-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 2px dashed rgba(255,255,255,0.15);
    padding-bottom: 20px;
  }

  .platform-name {
    font-size: 42px;
    font-weight: 600;
  }

  .platform-users {
    font-size: 46px;
    font-weight: 800;
    color: var(--accent-cyan);
  }

  /* Section 4 */
  .economy-impact {
    text-align: center;
    padding: 30px 0 60px 0;
  }

  .econ-val {
    font-size: 180px;
    font-weight: 900;
    color: var(--text-primary);
    text-shadow: 0 0 50px rgba(0, 119, 255, 0.6);
    line-height: 1;
  }

  .econ-label {
    font-size: 50px;
    color: var(--accent-blue);
    font-weight: 600;
    margin-top: 20px;
    text-transform: uppercase;
    letter-spacing: 2px;
  }

  .econ-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }

  .econ-box {
    background: rgba(255,255,255,0.04);
    padding: 45px;
    border-radius: 25px;
    border-left: 8px solid var(--accent-teal);
  }

  .econ-box h4 {
    font-size: 55px;
    color: var(--accent-cyan);
    margin: 0 0 20px 0;
  }

  .econ-box p {
    font-size: 34px;
    color: var(--text-secondary);
    margin: 0;
    line-height: 1.5;
  }

  .footer {
    text-align: center;
    font-size: 28px;
    color: rgba(255,255,255,0.4);
    margin-top: auto;
    padding-top: 30px;
    border-top: 2px solid rgba(255,255,255,0.1);
  }

</style>
</head>
<body>
  <div class="bg-pattern"></div>
  <div class="container">

    <header>
      <h1>Global Internet Usage: A Cross-Country Comparison</h1>
      <div class="subtitle">A data-driven comparison of internet penetration, digital population size, and online behavior across the world's leading digital economies.</div>
    </header>

    <div class="hero-stat">
      <div class="hero-number">~5.56 BILLION</div>
      <div class="hero-label">Global Internet Users (2025)</div>
      <div class="hero-sublabel">Representing ~68% of the global population</div>
    </div>

    <div class="main-grid">

      <!-- Card 1 -->
      <div class="card">
        <div class="card-title">The World's Digital Population</div>
        <div class="population-grid">
          <div class="pop-highlight">
            <div class="country">China</div>
            <div class="value">~1.09B</div>
            <div class="label">Online Population</div>
          </div>
          <div class="pop-highlight">
            <div class="country">India</div>
            <div class="value">~900M</div>
            <div class="label">Online Population</div>
          </div>
        </div>
        <div class="other-countries">
          Asia dominates in absolute online population, far outpacing other regions. The <span>United States (~320M)</span> remains the third-largest market, followed closely by <span>Indonesia (~220M)</span> and <span>Brazil (~190M)</span>. Developing nations present massive opportunities for continued connectivity growth.
        </div>
      </div>

      <!-- Card 2 -->
      <div class="card">
        <div class="card-title">Internet Penetration Rates</div>
        <div class="chart-container">
          <div class="bar-row">
            <div class="bar-label">South Korea</div>
            <div class="bar-track"><div class="bar-fill high" style="width: 98%;">98%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">UK</div>
            <div class="bar-track"><div class="bar-fill high" style="width: 97%;">97%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">Germany</div>
            <div class="bar-track"><div class="bar-fill high" style="width: 96%;">96%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">Japan</div>
            <div class="bar-track"><div class="bar-fill high" style="width: 95%;">95%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">USA</div>
            <div class="bar-track"><div class="bar-fill high" style="width: 95%;">95%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">Brazil</div>
            <div class="bar-track"><div class="bar-fill med" style="width: 88%;">88%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">Indonesia</div>
            <div class="bar-track"><div class="bar-fill med" style="width: 78%;">78%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">China</div>
            <div class="bar-track"><div class="bar-fill med" style="width: 76%;">76%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">India</div>
            <div class="bar-track"><div class="bar-fill low" style="width: 62%;">62%</div></div>
          </div>
          <div class="bar-row">
            <div class="bar-label">Nigeria</div>
            <div class="bar-track"><div class="bar-fill low" style="width: 52%;">52%</div></div>
          </div>
        </div>
      </div>

      <!-- Card 3 -->
      <div class="card">
        <div class="card-title">How People Spend Time Online</div>
        <div class="usage-stat">
          <div class="usage-stat-val">143<span style="font-size:70px">m</span></div>
          <div class="usage-stat-desc">Average Daily Social Media Usage per user globally (2025)</div>
        </div>
        <div style="font-size: 36px; color: var(--text-secondary); margin-bottom: 20px; font-weight: 600;">Top Platforms by Monthly Active Users:</div>
        <div class="platforms">
          <div class="platform-row">
            <div class="platform-name">Facebook</div>
            <div class="platform-users">~3.1 Billion</div>
          </div>
          <div class="platform-row">
            <div class="platform-name">YouTube</div>
            <div class="platform-users">~2.5 Billion</div>
          </div>
          <div class="platform-row">
            <div class="platform-name">WhatsApp</div>
            <div class="platform-users">~2.4 Billion</div>
          </div>
          <div class="platform-row">
            <div class="platform-name">Instagram</div>
            <div class="platform-users">~2.0 Billion</div>
          </div>
          <div class="platform-row">
            <div class="platform-name">TikTok</div>
            <div class="platform-users">~1.6 Billion</div>
          </div>
        </div>
      </div>

      <!-- Card 4 -->
      <div class="card">
        <div class="card-title">The Digital Economy Impact</div>
        <div class="economy-impact">
          <div class="econ-val">$8.0<span style="font-size: 100px">T</span></div>
          <div class="econ-label">Global Retail E-Commerce Sales (2027 est.)</div>
        </div>
        <div class="econ-grid">
          <div class="econ-box">
            <h4>> 60%</h4>
            <p>Mobile internet traffic share of all web traffic worldwide.</p>
          </div>
          <div class="econ-box">
            <h4>$800B</h4>
            <p>Projected size of the AI market by 2030.</p>
          </div>
          <div class="econ-box" style="grid-column: span 2;">
            <h4>180+ ZB</h4>
            <p>Total estimated global data generation by 2025.</p>
          </div>
        </div>
      </div>

    </div>

    <div class="footer">
      Generated for Data Report • Source: Global Internet Connectivity Brief 2025
    </div>

  </div>
</body>
</html>
EOF
